#include <bits/stdc++.h>
using namespace std;

#define FOR_LOOP(i, n) for (int i = 0; i < (int)(n); ++i)
#define add_back v_b
#define insert_back v_e
#define first_elem f
#define second_elem s
typedef long long ll;
typedef vector<int> vec;
typedef pair<int, int> pair_t;
typedef long double ld;

const int MAX_LIMIT = 21;
const ld TOL = 1e-6;

int count_m = 0, k_req, total_m;
ld probs[MAX_LIMIT];
int order[MAX_LIMIT];
ld dp_state[1 << MAX_LIMIT];
ld output[MAX_LIMIT];

void read_input() {
    cin >> total_m >> k_req;
    for (int i = 0; i < total_m; ++i) {
        ld val;
        cin >> val;
        if (val > TOL) {
            probs[count_m] = val;
            order[count_m] = i;
            ++count_m;
        } else {
            output[i] = 0;
        }
    }
}

void process() {
    if (k_req >= count_m) {
        for (int i = 0; i < count_m; ++i)
            output[order[i]] = 1.0;
    } else {
        dp_state[0] = 1.0;
        for (int mask = 0; mask < (1 << count_m); ++mask) {
            if (__builtin_popcount(mask) < k_req) {
                ld sum_prob = 0.0;
                for (int t = 0; t < count_m; ++t)
                    if (!((mask >> t) & 1))
                        sum_prob += probs[t];
                for (int t = 0; t < count_m; ++t)
                    if (!((mask >> t) & 1))
                        dp_state[mask ^ (1 << t)] += probs[t] / sum_prob * dp_state[mask];
            }
        }
        for (int mask = 0; mask < (1 << count_m); ++mask) {
            if (__builtin_popcount(mask) == k_req) {
                for (int t = 0; t < count_m; ++t)
                    if ((mask >> t) & 1)
                        output[order[t]] += dp_state[mask];
            }
        }
    }
    for (int i = 0; i < total_m; ++i)
        cout << output[i] << " ";
    cout << endl;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.precision(10);
    cout << fixed;
    read_input();
    process();
    return 0;
}
